document$.subscribe(function(){function banner_svg_image_fill(){const svg_images=document.querySelectorAll(".custom-bg .banner-hover-effect svg image");if(!svg_images)return;svg_images.forEach(imageNode=>{imageNode.setAttribute("href","home/images/Click_BK.png");const li=imageNode.closest('li');const a=imageNode.closest('a');li.addEventListener('click',event=>{a.click();});a.addEventListener('click',async(e)=>{e.stopPropagation();});});}
banner_svg_image_fill();function banner_svg_text_to_tspan(){const svg_texts=document.querySelectorAll(".custom-bg .banner-hover-effect svg text");if(!svg_texts)return;svg_texts.forEach(textNode=>{const originalText=textNode.textContent.trim();textNode.textContent='';const words=originalText.split(/\s+/);words.forEach((word,index)=>{const tspan=document.createElementNS("http://www.w3.org/2000/svg","tspan");tspan.textContent=word;tspan.setAttribute("class","word-span");tspan.setAttribute("data-word-index",index);textNode.appendChild(tspan);if(index<words.length-1){textNode.appendChild(document.createTextNode(" "));}});});}
banner_svg_text_to_tspan();function banner_svg_tspan_highlight(padding=0){const svg_texts=document.querySelectorAll(".custom-bg .banner-hover-effect svg text tspan");if(!svg_texts)return;svg_texts.forEach(async tspanNode=>{const queries=window.location.href.replace(/\#.*/g,"").replace(/.*\?/g,"").split("&");let keys=[];queries.forEach(query=>{if(query.length>2){const el=query.split("=");if(el[0]==="h"){keys=el[1].split("%20")}}});await keys.forEach(key=>{const index=tspanNode.textContent.toLowerCase().indexOf(key.toLowerCase());if(index>-1){let bbox=tspanNode.getBBox();const svgNamespace="http://www.w3.org/2000/svg";const rect=document.createElementNS(svgNamespace,"rect");if(tspanNode.textContent.length!=key.length){const tspanSubNode=document.createElementNS("http://www.w3.org/2000/svg","tspan");tspanSubNode.textContent=tspanNode.textContent.slice(index,index+key.length);tspanNode.appendChild(tspanSubNode);const bboxSub=tspanSubNode.getBBox();bbox.width=bboxSub.width;if(index>0){const tspanSubNodeF=document.createElementNS("http://www.w3.org/2000/svg","tspan");tspanSubNodeF.textContent=tspanNode.textContent.slice(0,index+key.length);tspanNode.appendChild(tspanSubNodeF);const bboxSubF=tspanSubNodeF.getBBox();bbox.x=bbox.x+bboxSubF.width-bboxSub.width;bbox.width=bboxSub.width;tspanNode.removeChild(tspanSubNodeF);}
tspanNode.removeChild(tspanSubNode);}
rect.setAttribute("x",bbox.x-padding);rect.setAttribute("y",bbox.y-padding);rect.setAttribute("width",bbox.width+(padding*2));rect.setAttribute("height",bbox.height+(padding*2));rect.setAttribute("class","svg-tspan-highlight");rect.setAttribute("rx","4");const textNode=tspanNode.closest('text');textNode.parentNode.insertBefore(rect,textNode);}});});}
banner_svg_tspan_highlight();})